ROOT = Path(__file__).resolve().parent


def profile(key, name, category, surfaces, anchors, proof, forbidden, gap, sources, adapter="none", demand=None):
    return {"id": key, "name": name, "category": category,
            "priority": "Named by Lorenzo" if key in CORE else "Demand expansion",
            "surfaces": surfaces.split(" | "), "visualAnchors": anchors.split(" | "),
            "salesProof": proof.split(" | "), "neverSubstitute": forbidden,
            "remainingWork": gap, "sourceIds": sources.split() if sources else [],
            "currentAdapter": adapter, "productionReady": False,
            "demandName": demand or name,
            "state": "reference-plan; implementation and native comparison pending"}


